def codex_command(
    *,
    codex_bin: str,
    workspace: Path,
    model: str | None,
    use_sandbox_approval: bool,
    sandbox: str,
    approval: str,
    final_message_file: Path,
    extra_args: Sequence[str],
    prompt: str,
) -> list[str]:
    command = [
        codex_bin,
        "exec",
        "-C",
        str(workspace),
        "--json",
    ]
    if use_sandbox_approval:
        command.extend(["--sandbox", sandbox, "-a", approval])
    else:
        command.append("--dangerously-bypass-approvals-and-sandbox")
    command.extend(["-o", str(final_message_file)])
    if model:
        command.extend(["-m", model])
    command.extend(extra_args)
    command.append(prompt)
    return command


def extract_usage(path: Path) -> dict[str, Any] | None:
    usage: dict[str, Any] | None = None
    if not path.exists():
        return None
    for line in path.read_text(encoding="utf-8").splitlines():
        if not line.strip():
            continue
        event = json.loads(line)
        candidate = event.get("usage")
        if isinstance(candidate, dict):
            usage = candidate
    return usage


def usage_summary(results: Sequence[PhaseResult]) -> dict[str, Any]:
    by_phase: dict[str, Any] = {}
    totals = {
        "input_tokens": 0,
        "cached_input_tokens": 0,
        "output_tokens": 0,
        "reasoning_output_tokens": 0,
    }
    missing_usage: list[str] = []
    for result in results:
        usage = result.usage
        by_phase[result.phase] = {
            "usage": usage,
            "elapsed_seconds": result.elapsed_seconds,
            "exit_code": result.exit_code,
        }
        if usage is None:
            missing_usage.append(result.phase)
            continue
        for key in totals:
            value = usage.get(key)
            if isinstance(value, int):
                totals[key] += value
    return {
        "totals": totals,
        "missing_usage_phases": missing_usage,
        "by_phase": by_phase,
    }


def default_run_id() -> str:
    return datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ")


def current_branch(workspace: Path) -> str:
    completed = subprocess.run(
        ["git", "branch", "--show-current"],
        cwd=workspace,
        text=True,
        capture_output=True,
        check=False,
    )
    branch = completed.stdout.strip()
    return branch or "unknown"


def read_optional_text(path: Path) -> str:
    if not path.exists():
        return ""
    return path.read_text(encoding="utf-8").strip()


def write_json(path: Path, payload: Any) -> None:
    path.write_text(json.dumps(payload, indent=2, sort_keys=True) + "\n", encoding="utf-8")


